// GET /api/p101/vibration?minutes=5
// Liefert die Messwerte der letzten Minuten (Standard 5, höchstens 60) als JSON.
msg.headers = {
    "Content-Type": "application/json",
    "Access-Control-Allow-Origin": "*",   // Webapp auf GitHub Pages darf abfragen
    "Cache-Control": "no-store"
};

const db = flow.get("p101db");
if (!db) {
    msg.statusCode = 503;
    msg.payload = { error: "Datenbank nicht bereit" };
    return msg;
}

let minutes = parseInt(msg.req.query.minutes, 10);
if (!Number.isFinite(minutes)) minutes = 5;
minutes = Math.min(Math.max(minutes, 1), 60);

const seit = Date.now() - minutes * 60 * 1000;
const rows = db.prepare("SELECT ts, value FROM vibration WHERE ts >= ? ORDER BY ts").all(seit);

msg.statusCode = 200;
msg.payload = {
    source: "P-101 Vibration",
    unit: "mm/s",
    minutes: minutes,
    count: rows.length,
    data: rows.map(r => ({ timestamp: new Date(r.ts).toISOString(), value: r.value }))
};
return msg;

// Durchschnitt der letzten Minuten (Standard 5, höchstens 60).
// Kommt die Nachricht vom REST-Endpunkt (msg.req), geht die Antwort an Ausgang 1.
// Kommt sie vom Zeitgeber, geht ein Text an das Dashboard (Ausgang 2).
const db = flow.get("p101db");
const vomRest = !!msg.req;

if (vomRest) {
    msg.headers = {
        "Content-Type": "application/json",
        "Access-Control-Allow-Origin": "*",   // Webapp auf GitHub Pages darf abfragen
        "Cache-Control": "no-store"
    };
}
if (!db) {
    if (!vomRest) return null;
    msg.statusCode = 503;
    msg.payload = { error: "Datenbank nicht bereit" };
    return [msg, null];
}

let minutes = vomRest ? parseInt(msg.req.query.minutes, 10) : 5;
if (!Number.isFinite(minutes)) minutes = 5;
minutes = Math.min(Math.max(minutes, 1), 60);
const seit = Date.now() - minutes * 60 * 1000;

const r = db.prepare(`
    SELECT AVG(value) AS avg, MIN(value) AS min, MAX(value) AS max, COUNT(*) AS n
    FROM vibration
    WHERE ts >= ?
`).get(seit);

const runden = v => (v === null || v === undefined) ? null : Math.round(v * 1000) / 1000;
const ergebnis = {
    source: "P-101 Vibration",
    unit: "mm/s",
    minutes: minutes,
    count: r.n,
    average: runden(r.avg),
    min: runden(r.min),
    max: runden(r.max)
};

if (vomRest) {
    msg.statusCode = 200;
    msg.payload = ergebnis;
    return [msg, null];
}
const text = ergebnis.count
    ? ergebnis.average.toFixed(2).replace(".", ",") + " mm/s (" + ergebnis.count + " Werte)"
    : "noch keine Werte";
node.status({ text: "Ø " + text });
return [null, { payload: text }];

// Wertet jede Nachricht unter /bbk-lf7/<kiste>/power-house/vibration aus,
// auch die eigene. Je Topic wird festgehalten, wie oft, in welchem Format und mit welchen Werten gesendet wird.
const teile = msg.topic.split("/");
const stelle = teile.indexOf("bbk-lf7");
const kiste = stelle >= 0 ? teile[stelle + 1] : "?";
const roh = Buffer.isBuffer(msg.payload) ? msg.payload.toString("utf8") : String(msg.payload);

let format = "Text", wert = null, felder = [];
try {
    const obj = JSON.parse(roh);
    if (typeof obj === "number") {
        format = "Zahl";
        wert = obj;
    } else if (obj && typeof obj === "object") {
        format = Array.isArray(obj) ? "JSON-Liste" : "JSON-Objekt";
        felder = Array.isArray(obj) ? [] : Object.keys(obj).sort();
        // Wert direkt (value, vibration, …) oder verschachtelt wie im rohen OPC-UA-DataValue (value.value)
        const innen = obj.value && typeof obj.value === "object" ? obj.value.value : undefined;
        const kandidat = [obj.value, obj.vibration, obj.wert, obj.payload, innen].find(v => typeof v === "number");
        if (kandidat !== undefined) wert = kandidat;
        if (innen !== undefined) format = "JSON-Objekt (OPC-UA-DataValue)";
    } else {
        format = "JSON (" + typeof obj + ")";
    }
} catch (e) {
    if (/^\s*-?\d+([.,]\d+)?\s*$/.test(roh)) {
        format = "Zahl als Text";
        wert = parseFloat(roh.replace(",", "."));
    }
}

const EIGENE_KISTE = "18";
const jetzt = Date.now();
const alle = flow.get("gruppen") || {};
const g = alle[msg.topic] || {
    topic: msg.topic, kiste: kiste, eigene: kiste === EIGENE_KISTE,
    anzahl: 0, erste: jetzt, bytes: 0, retained: 0, formate: {}, felder: [],
    min: null, max: null, summe: 0, werteAnzahl: 0
};
g.anzahl++;
g.letzte = jetzt;
g.bytes += Buffer.byteLength(roh);
if (msg.retain) g.retained++;
g.formate[format] = (g.formate[format] || 0) + 1;
g.felder = [...new Set(g.felder.concat(felder))].sort();
if (wert !== null && Number.isFinite(wert)) {
    g.min = g.min === null ? wert : Math.min(g.min, wert);
    g.max = g.max === null ? wert : Math.max(g.max, wert);
    g.summe += wert;
    g.werteAnzahl++;
    g.letzterWert = wert;
}
g.beispiel = roh.slice(0, 300);
alle[msg.topic] = g;
flow.set("gruppen", alle);

const fremde = Object.values(alle).filter(x => !x.eigene).length;
node.status({ fill: fremde ? "green" : "grey", shape: "dot", text: fremde + " fremde Gruppen gehört" });
msg.kiste = kiste;
msg.format = format;
return msg;

// GET /api/bbk-lf7/gruppen: Vergleich aller gehörten Topics als JSON
msg.headers = {
    "Content-Type": "application/json",
    "Access-Control-Allow-Origin": "*",
    "Cache-Control": "no-store"
};
const jetzt = Date.now();
const runden = v => (v === null || v === undefined) ? null : Math.round(v * 1000) / 1000;
const alle = Object.values(flow.get("gruppen") || {});
msg.payload = {
    seit: alle.length ? new Date(Math.min(...alle.map(g => g.erste))).toISOString() : null,
    gruppen: alle.sort((a, b) => a.topic.localeCompare(b.topic, "de", { numeric: true })).map(g => {
        const sekunden = Math.max((g.letzte - g.erste) / 1000, 1);
        return {
            topic: g.topic,
            kiste: g.kiste,
            eigene: g.eigene,
            nachrichten: g.anzahl,
            proMinute: g.anzahl > 1 ? Math.round((g.anzahl - 1) / sekunden * 60 * 10) / 10 : null,
            zuletztVorSekunden: Math.round((jetzt - g.letzte) / 1000),
            durchschnittBytes: Math.round(g.bytes / g.anzahl),
            retained: g.retained,
            formate: g.formate,
            felder: g.felder,
            werte: g.werteAnzahl ? { min: runden(g.min), max: runden(g.max), durchschnitt: runden(g.summe / g.werteAnzahl), letzter: runden(g.letzterWert) } : null,
            beispiel: g.beispiel
        };
    })
};
msg.statusCode = 200;
return msg;

// Messwert für das Dashboard aufbereiten:
// Ausgang 1: Zahl für Tacho und Diagramm, Ausgang 2: Text mit Wert und Uhrzeit
const wert = msg.payload.value;
const zeit = new Date(msg.payload.timestamp).toLocaleTimeString("de-DE", { timeZone: "Europe/Berlin" });
return [
    { payload: Math.round(wert * 100) / 100, topic: "P-101" },
    { payload: wert.toFixed(2).replace(".", ",") + " mm/s um " + zeit }
];
